using System;using System.Linq;using System.IO;using System.Reflection;using Verse;using Verse.AI;using RimWorld;using PlayableRecreation;using PlayableRecreation.UI;using PRQA;
public static class Command{public static string Run(){var log=Host.Root+"/final-runtime.txt";Action<string> note=s=>File.AppendAllText(log,s+"\n");var f=BindingFlags.Instance|BindingFlags.NonPublic;var pair=(Pawn[])Host.State["finalPair"];var p=pair[0];var o=pair[1];var b=(Thing)Host.State["chess"];var game=b.TryGetComp<CompMiniGame>().Game;var comp=GameComponent_Recreation.Current;var d=Find.WindowStack.Windows.OfType<Dialog_MiniGame>().First();note("practice ended="+((MiniGameWorker)typeof(Dialog_MiniGame).GetField("worker",f).GetValue(d)).IsOver);typeof(Dialog_MiniGame).GetMethod("StartAnotherMatch",f).Invoke(d,null);int stage=0,start=Find.TickManager.TicksGame;Host.Watch=()=>{int elapsed=Find.TickManager.TicksGame-start;var w=Find.WindowStack.Windows.OfType<Dialog_MiniGame>().FirstOrDefault();if(stage==0&&(w!=null||elapsed>900)){note("practice New game opened="+(w!=null)+" sameOpponent="+(w!=null&&typeof(Dialog_MiniGame).GetField("opponentPawn",f).GetValue(w)==o)+" practice="+(w==null?null:typeof(Dialog_MiniGame).GetField("practice",f).GetValue(w)));w?.Close();TogetherMatch.Reset();PRMod.Settings.playTogether=false;GameEntry.Commit(game,b,p,null,2,false);stage=1;start=Find.TickManager.TicksGame;}else if(stage==1&&w!=null){w.Close();Host.State["exitPawnPos"]=p.Position;p.jobs.EndCurrentJob(JobCondition.InterruptForced);p.DeSpawn();note("solo pawn despawned, stored="+(comp.SessionFor(b)!=null));stage=2;start=Find.TickManager.TicksGame;}else if(stage==2&&elapsed>180){note("solo map-exit "+elapsed+" ticks stored="+(comp.SessionFor(b)!=null));GenSpawn.Spawn(p,(IntVec3)Host.State["exitPawnPos"],b.Map);Find.TickManager.CurTimeSpeed=TimeSpeed.Paused;Host.Watch=null;}};Find.TickManager.CurTimeSpeed=TimeSpeed.Superfast;return "Practice rematch then solo map-exit persistence started.";}}
